      "content": "OO國小森林教室裡，小刺蝟波波個性溫柔害羞，平時同學喜歡捏他的臉頰或突然從背後抱住他。雖然波波覺得很不舒服，但因為怕同學生氣，總是忍耐不敢出聲。\n\n老師看出波波的苦惱，溫柔地對他說：『波波，你的身體是你最珍貴的寶物！如果不舒服，你有權利保護自己！』老師教他挺起胸膛，伸直手掌掌心向前，大聲堅定地說：『請停下來！我不喜歡這樣！』下課時，有同學又想伸手捏臉，波波立刻立正、伸出手掌大聲喊停。同學愣了一下，連忙道歉退開。波波發現，原來勇敢說不，別人才會真正懂得尊重他！",
      "question": "當別人對你做不舒服的動作時，忍耐不說會解決問題嗎？勇敢說「不」的時候，眼神和手部動作應該怎麼做？"
