    "story": {
      "title": "⏰ 大公雞的清晨咕咕啼與彩色作息大圓盤！",
      "content": "暑假的第一週，小畯整個人像洩了氣的皮球，第一天就看電視到半夜一點，第二天睡到中午十二點才起床，頭昏腦脹、脾氣暴躁，還跟媽媽大吵了一架。\n\n下午，老師在線上特教班會中拿出了『彩色作息大圓盤』：『孩子們，暑假是學習「做自己時間主人」的最好機會！如果作息顛倒，大腦就會生鏽變笨喔！』小畯看著小宇分享的行程表：早上八點起床跳繩、九點寫作業、下午三點騎腳踏車、晚上十點睡覺。小畯心裡好佩服，立刻拿畫筆畫了一張屬於自己的『無敵暑假作息表』貼在冰箱上。從那天起，小畯每天早上自己按掉鬧鐘起床，整個人容光煥發！",
      "question": "放暑假如果每天打電動到半夜、睡到中午，身體和大腦會變得怎麼樣？規律生活為什麼會讓人更快樂？"
    },
